+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package promql
+
+import (
+	"cmp"
+	"math/big"
+	"net/netip"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+
+	"github.com/facette/natsort"
+	"github.com/grafana/regexp"
+	"golang.org/x/mod/semver"
+)
+
+type labelValueKind uint8
+
+// Classify each operand independently. Choosing a parser based on whether both
+// operands parse would make comparisons between mixed domains non-transitive.
+const (
+	labelWhitespace labelValueKind = iota
+	labelPositiveInf
+	labelNumber
+	labelNegativeInf
+	labelDuration
+	labelBytes
+	labelVersion
+	labelIP
+	labelPrefix
+	labelTimestamp
+	labelString
+)
+
+type parsedLabelValue struct {
+	kind      labelValueKind
+	magnitude labelMagnitude
+	version   string
+	address   netip.Addr
+	prefix    int
+	timestamp time.Time
+}
+
+func compareLabelValues(a, b string) int {
+	if a == b {
+		return 0
+	}
+	x, y := parseLabelValue(a), parseLabelValue(b)
+	if c := cmp.Compare(x.kind, y.kind); c != 0 {
+		return c
+	}
+	var c int
+	switch x.kind {
+	case labelNumber, labelDuration, labelBytes:
+		c = x.magnitude.Cmp(y.magnitude)
+	case labelVersion:
+		c = semver.Compare(x.version, y.version)
+	case labelIP, labelPrefix:
+		// Addr.Compare orders IPv4 before IPv6 without unmapping mapped IPv6.
+		c = x.address.Compare(y.address)
+		if c == 0 && x.kind == labelPrefix {
+			c = cmp.Compare(x.prefix, y.prefix)
+		}
+	case labelTimestamp:
+		c = x.timestamp.Compare(y.timestamp)
+	}
+	if c != 0 {
+		return c
+	}
+	less, greater := natsort.Compare(a, b), natsort.Compare(b, a)
+	if less != greater {
+		if less {
+			return -1
+		}
+		return 1
+	}
+	// Natural sorting can report both directions as less for equal digit runs
+	// with different leading zeros. Resolve such ties consistently.
+	return strings.Compare(a, b)
+}
+
+const labelNumberPattern = `[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?`
+
+var (
+	labelNumberRE   = regexp.MustCompile(`^` + labelNumberPattern + `$`)
+	labelDurationRE = regexp.MustCompile(`^(` + labelNumberPattern + `)(ns|us|µs|μs|ms|s|m|h|d|w|y)`)
+	labelBytesRE    = regexp.MustCompile(`^(` + labelNumberPattern + `)\s*((?:[kKMGTPEZY]i?)?B)$`)
+)
+
+var labelDurationUnits = map[string]int64{
+	"ns": 1, "us": 1000, "µs": 1000, "μs": 1000, "ms": 1000000,
+	"s": 1000000000, "m": 60 * 1000000000, "h": 3600 * 1000000000,
+	"d": 86400 * 1000000000, "w": 7 * 86400 * 1000000000, "y": 365 * 86400 * 1000000000,
+}
+
+func parseLabelValue(s string) parsedLabelValue {
+	first, _ := utf8.DecodeRuneInString(s)
+	if unicode.IsSpace(first) {
+		return parsedLabelValue{kind: labelWhitespace}
+	}
+	switch strings.ToLower(s) {
+	case "inf", "+inf", "infinity", "+infinity":
+		return parsedLabelValue{kind: labelPositiveInf}
+	case "-inf", "-infinity":
+		return parsedLabelValue{kind: labelNegativeInf}
+	}
+	if labelNumberRE.MatchString(s) {
+		return parsedLabelValue{kind: labelNumber, magnitude: labelMagnitude{parseLabelDecimal(s)}}
+	}
+	if n, ok := parseLabelDuration(s); ok {
+		return parsedLabelValue{kind: labelDuration, magnitude: n}
+	}
+	if parts := labelBytesRE.FindStringSubmatch(s); parts != nil {
+		n := parseLabelDecimal(parts[1])
+		unit := parts[2]
+		if unit != "B" {
+			power := int64(strings.IndexByte("KMGTPEZY", strings.ToUpper(unit[:1])[0]) + 1)
+			base := int64(1000)
+			if strings.Contains(unit, "i") {
+				base = 1024
+			}
+			factor := new(big.Int).Exp(big.NewInt(base), big.NewInt(power), nil)
+			n.coefficient.Mul(n.coefficient, factor)
+		}
+		return parsedLabelValue{kind: labelBytes, magnitude: labelMagnitude{n}}
+	}
+	version := s
+	if !strings.HasPrefix(version, "v") {
+		version = "v" + version
+	}
+	// x/mod/semver also accepts abbreviated versions. Labels require all three
+	// core components, and otherwise follow strict SemVer 2.0 validation.
+	core, _, _ := strings.Cut(version, "-")
+	core, _, _ = strings.Cut(core, "+")
+	if strings.Count(core, ".") == 2 && semver.IsValid(version) {
+		return parsedLabelValue{kind: labelVersion, version: version}
+	}
+	if address, err := netip.ParseAddr(s); err == nil {
+		return parsedLabelValue{kind: labelIP, address: address}
+	}
+	if prefix, err := netip.ParsePrefix(s); err == nil {
+		return parsedLabelValue{kind: labelPrefix, address: prefix.Masked().Addr(), prefix: prefix.Bits()}
+	}
+	if timestamp, err := time.Parse(time.RFC3339Nano, s); err == nil {
+		return parsedLabelValue{kind: labelTimestamp, timestamp: timestamp}
+	}
+	return parsedLabelValue{kind: labelString}
+}
+
+func parseLabelDuration(s string) (labelMagnitude, bool) {
+	if s == "" {
+		return nil, false
+	}
+	// A leading sign applies to the whole duration, as in time.ParseDuration.
+	negative := s[0] == '-'
+	if s[0] == '-' || s[0] == '+' {
+		s = s[1:]
+		if s == "" || s[0] == '-' || s[0] == '+' {
+			return nil, false
+		}
+	}
+	var total labelMagnitude
+	for s != "" {
+		parts := labelDurationRE.FindStringSubmatch(s)
+		if parts == nil {
+			return nil, false
+		}
+		n := parseLabelDecimal(parts[1])
+		n.coefficient.Mul(n.coefficient, big.NewInt(labelDurationUnits[parts[2]]))
+		if negative {
+			n.coefficient.Neg(n.coefficient)
+		}
+		total = append(total, n)
+		s = s[len(parts[0]):]
+	}
+	return total, len(total) != 0
+}
