+package promql
+
+import (
+	"cmp"
+	"math/big"
+	"slices"
+	"strings"
+)
+
+// Keep the exponent separate so even enormous scientific exponents require
+// space proportional to the label, rather than to the represented magnitude.
+type labelDecimal struct {
+	coefficient *big.Int
+	exponent    *big.Int
+}
+
+// A duration may contain several terms. Keeping the sum sparse avoids expanding
+// the gap between components such as 1e1000000000h1ns.
+type labelMagnitude []labelDecimal
+
+// parseLabelDecimal requires a string validated by labelNumberPattern.
+func parseLabelDecimal(s string) labelDecimal {
+	exponent := new(big.Int)
+	if i := strings.IndexAny(s, "eE"); i >= 0 {
+		exponent.SetString(s[i+1:], 10)
+		s = s[:i]
+	}
+	if i := strings.IndexByte(s, '.'); i >= 0 {
+		exponent.Sub(exponent, big.NewInt(int64(len(s)-i-1)))
+		s = s[:i] + s[i+1:]
+	}
+	coefficient, _ := new(big.Int).SetString(s, 10)
+	return labelDecimal{coefficient: coefficient, exponent: exponent}
+}
+
+func (a labelDecimal) cmp(b labelDecimal) int {
+	sign := a.coefficient.Sign()
+	if c := cmp.Compare(sign, b.coefficient.Sign()); c != 0 {
+		return c
+	}
+	if sign == 0 {
+		return 0
+	}
+	x := strings.TrimPrefix(a.coefficient.String(), "-")
+	y := strings.TrimPrefix(b.coefficient.String(), "-")
+	xOrder := new(big.Int).Add(a.exponent, big.NewInt(int64(len(x))))
+	yOrder := new(big.Int).Add(b.exponent, big.NewInt(int64(len(y))))
+	if c := xOrder.Cmp(yOrder); c != 0 {
+		return sign * c
+	}
+	// Compare significant digits, treating missing trailing digits as zeros.
+	for i := range max(len(x), len(y)) {
+		xDigit, yDigit := byte('0'), byte('0')
+		if i < len(x) {
+			xDigit = x[i]
+		}
+		if i < len(y) {
+			yDigit = y[i]
+		}
+		if c := cmp.Compare(xDigit, yDigit); c != 0 {
+			return sign * c
+		}
+	}
+	return 0
+}
+
+func (a labelMagnitude) Cmp(b labelMagnitude) int {
+	if len(a) == 1 && len(b) == 1 {
+		return a[0].cmp(b[0])
+	}
+	type digit struct {
+		position *big.Int
+		value    int
+	}
+	var digits []digit
+	appendDigits := func(terms labelMagnitude, direction int) {
+		for _, term := range terms {
+			sign := term.coefficient.Sign() * direction
+			s := strings.TrimPrefix(term.coefficient.String(), "-")
+			for i := range len(s) {
+				if s[i] == '0' {
+					continue
+				}
+				position := new(big.Int).Add(term.exponent, big.NewInt(int64(len(s)-i-1)))
+				digits = append(digits, digit{position, sign * int(s[i]-'0')})
+			}
+		}
+	}
+	appendDigits(a, 1)
+	appendDigits(b, -1)
+	slices.SortFunc(digits, func(a, b digit) int { return a.position.Cmp(b.position) })
+
+	// Normalize the difference from least to most significant digit. Signed
+	// remainders avoid borrowing across large gaps. Once each digit is in
+	// [-9, 9], the highest nonzero digit determines the sign of the difference.
+	carry, sign := 0, 0
+	position := new(big.Int)
+	one := big.NewInt(1)
+	for i := 0; i < len(digits); {
+		next := digits[i].position
+		for carry != 0 && position.Cmp(next) < 0 {
+			if remainder := carry % 10; remainder != 0 {
+				sign = cmp.Compare(remainder, 0)
+			}
+			carry /= 10
+			position.Add(position, one)
+		}
+		for i < len(digits) && digits[i].position.Cmp(next) == 0 {
+			carry += digits[i].value
+			i++
+		}
+		if remainder := carry % 10; remainder != 0 {
+			sign = cmp.Compare(remainder, 0)
+		}
+		carry /= 10
+		position.Add(next, one)
+	}
+	if carry != 0 {
+		return cmp.Compare(carry, 0)
+	}
+	return sign
+}
