+
+func TestCompareLabelValues(t *testing.T) {
+	// Each row is in strict ascending order. Check every pair, not just
+	// neighbors, to catch cycles caused by mixing typed and natural comparisons.
+	tests := map[string][]string{
+		"classes":                    {" 2", " 10", "+Inf", "-100", "100", "-Inf", "1s", "1B", "1.2.3", "127.0.0.1", "127.0.0.0/8", "2025-01-01T00:00:00Z", "", "NaN", "item2", "item10"},
+		"numbers":                    {"-1e400", "-100", "-2", "-0", "0", "+.1", ".2", "1e-2e", "NaN"},
+		"numeric precision":          {"-1e1000", "-1e999", "1e-1000", "1e-999", "9007199254740992", "9007199254740993", "1e999", "1e1000"},
+		"enormous exponents":         {"-1e100000000000000000000", "-1e99999999999999999999", "1e-100000000000000000000", "1e-99999999999999999999", "1e99999999999999999999", "1e100000000000000000000"},
+		"enormous durations":         {"1e100000000000000000000ns", "1e100000000000000000000us", "1e100000000000000000000ms", "1e100000000000000000000s"},
+		"enormous bytes":             {"1e100000000000000000000B", "1e100000000000000000000KB", "1e100000000000000000000KiB"},
+		"numeric ties":               {"+10", "1e1", "010", "10", "10.0"},
+		"duration":                   {"-2h", "-1h30m", "-30m", "0s", "1ns", "1us", "1ms", "1s", "1m", "1h", "1d", "1w", "1y", "1e400s", "1e401s"},
+		"signed scientific duration": {"-2e3ms", "-1e3ms", "+1e-3s", "2e-3s", "1e3ms", "2s"},
+		"duration precision":         {"9007199254740992ns", "9007199254740993ns", "1000000000000000000000000000000s", "1000000000000000000000000000001s"},
+		"duration ties":              {"+1s", "1e3ms", "1s", "1000ms"},
+		"bytes":                      {"-2GB", "-1GB", "0B", "1B", "1kB", "1KiB", "1MB", "1MiB", "1GB", "1GiB", "1YB", "1YiB", "1e400B", "1e401B"},
+		"signed scientific bytes":    {"-2e3B", "-1e3B", "+1e-3B", "2e-3B", "1e3B", "2KB"},
+		"byte precision":             {"9007199254740992B", "9007199254740993B", "1000000000000000000000000000000B", "1000000000000000000000000000001B"},
+		"byte ties":                  {"+1KiB", "1KiB", "1024B"},
+		"versions":                   {"v1.0.0-alpha", "1.0.0-alpha.2", "1.0.0-alpha.10", "1.0.0-beta", "1.0.0-rc.1", "1.0.0", "1.0.0+build2", "1.0.0+build10", "v1.0.0", "1.0.1", "1.2.0", "1.10.0", "2.0.0"},
+		"version precision":          {"1.0.0-99999999999999999999", "1.0.0-100000000000000000000", "99999999999999999999.0.0", "100000000000000000000.0.0"},
+		"IP":                         {"2.0.0.1", "10.0.0.1", "255.255.255.255", "::1", "::ffff:0.0.0.1", "2001:db8::2", "2001:db8::10"},
+		"CIDR":                       {"10.0.0.0/8", "10.0.0.0/16", "10.0.0.1/16", "10.0.1.0/24", "255.0.0.0/8", "::/0", "::/64", "::ffff:0.0.0.0/96", "2001:db8::/32", "2001:db8::/64"},
+		"timestamps":                 {"2025-01-01T01:00:00+02:00", "2025-01-01T00:00:00Z", "2025-01-01T01:00:00+01:00", "2025-01-01T00:00:00.000000001Z", "2025-01-01T00:00:00.1Z"},
+		"untyped":                    {"", "1e", "1e+", "1e-", "NaN", "item2", "item10"},
+		"whitespace":                 {"\t1s", " 2", " 10", " NaN", " v1.0.0", "\u00a01B", "\u20031", "+Inf"},
+	}
+	for name, values := range tests {
+		t.Run(name, func(t *testing.T) {
+			for i, a := range values {
+				for j, b := range values {
+					require.Equal(t, cmp.Compare(i, j), cmp.Compare(compareLabelValues(a, b), 0), "%q vs %q", a, b)
+				}
+			}
+			for seed := range int64(5) {
+				shuffled := slices.Clone(values)
+				rand.New(rand.NewSource(seed)).Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })
+				slices.SortFunc(shuffled, compareLabelValues)
+				require.Equal(t, values, shuffled)
+			}
+		})
+	}
+}
+
+func TestLabelValueClassification(t *testing.T) {
+	for _, s := range []string{"", "NaN", "+NaN", "-NaN", "nan", "1e", "1E+", "1e-", "1eB", "1ems", "0x10", "1_000", "1.0.0.0.0", "v1", "v1.2", "01.2.3", "1.02.3", "1.2.03", "1.2.3-01", "1.2.3-", "1.2.3+", "1.2.3+bad!", "256.0.0.1", "10.0.0.0/33", "2025-02-30T00:00:00Z", "1s ", "1iB", "--1s", "-+1s", "+-1s", "++1s"} {
+		require.Equal(t, labelString, parseLabelValue(s).kind, "%q", s)
+	}
+	for _, s := range []string{"1", "+1", "08", "010", "1.", ".1", "1e1", "1E+10", "1e-10", strings.Repeat("9", 1000)} {
+		require.Equal(t, labelNumber, parseLabelValue(s).kind, "%q", s)
+	}
+	for _, s := range []string{" +Inf", "\t1", " -Inf", " 1s", " 1B", " v1.2.3", " ::1", " 10.0.0.0/8", " 2025-01-01T00:00:00Z", " ", "\u2003NaN"} {
+		require.Equal(t, labelWhitespace, parseLabelValue(s).kind, "%q", s)
+	}
+}
+
+func FuzzCompareLabelValues(f *testing.F) {
+	f.Add("10", "2s", "1e")
+	f.Add("1e400", "1e401", "1e402")
+	f.Add("1.0.0", "v1.0.0", "1.0.0+build")
+	f.Add(" 2", " 10", "")
+	f.Fuzz(func(t *testing.T, a, b, c string) {
+		ab := compareLabelValues(a, b)
+		require.Equal(t, -cmp.Compare(ab, 0), cmp.Compare(compareLabelValues(b, a), 0))
+		require.Equal(t, a == b, ab == 0)
+		if ab <= 0 && compareLabelValues(b, c) <= 0 {
+			require.LessOrEqual(t, compareLabelValues(a, c), 0)
+		}
+	})
+}
+
+// Check exact arithmetic against an independent rational implementation at
+// manageable exponents, including mixed signs, cancellation, and carries.
+func TestLabelMagnitude(t *testing.T) {
+	rng := rand.New(rand.NewSource(1))
+	for range 1000 {
+		var magnitudes [2]labelMagnitude
+		var rationals [2]big.Rat
+		for i := range magnitudes {
+			for range 1 + rng.Intn(8) {
+				s := fmt.Sprintf("%de%d", rng.Intn(20001)-10000, rng.Intn(81)-40)
+				magnitudes[i] = append(magnitudes[i], parseLabelDecimal(s))
+				r, ok := new(big.Rat).SetString(s)
+				require.True(t, ok)
+				rationals[i].Add(&rationals[i], r)
+			}
+		}
+		require.Equal(t, rationals[0].Cmp(&rationals[1]), magnitudes[0].Cmp(magnitudes[1]))
+		require.Zero(t, magnitudes[0].Cmp(magnitudes[0]))
+	}
+	for _, pair := range [][2]string{
+		{"1e100000000000000000000h1ns", "1e100000000000000000000h2ns"},
+		{"1e-100000000000000000000h1ns", "1e-100000000000000000000h2ns"},
+		{"1e100000000000000000000h", "1e100000000000000000000h1ns"},
+		{"-1e100000000000000000000h1ns", "-1e100000000000000000000h"},
+		{"1h-60m", "1ns"},
+		{"99ns1ns", "101ns"},
+	} {
+		a, ok := parseLabelDuration(pair[0])
+		require.True(t, ok)
+		b, ok := parseLabelDuration(pair[1])
+		require.True(t, ok)
+		require.Equal(t, -1, a.Cmp(b), "%v", pair)
+		require.Equal(t, 1, b.Cmp(a), "%v", pair)
+	}
+}
